// ID Card Actions - Edit UI Sub-module
// Contains: Cell editing UI (start/cancel), editable hints, image preview
// Split from: idcard-actions-edit.js

(function() {
'use strict';

window.IDCardApp = window.IDCardApp || {};

// ==========================================
// HELPER FUNCTIONS
// ==========================================

function getAdjacentCell(currentCell, direction) {
    const row = currentCell.closest('tr');
    // Only select text cells that are editable (excludes image-field, action, SR NO, dates)
    const allCells = Array.from(row.querySelectorAll('td.editable-cell[data-field]:not(.image-field)'));
    const currentIndex = allCells.indexOf(currentCell);
    
    if (direction === 'next') {
        // Try next cell in same row
        if (currentIndex + 1 < allCells.length) {
            return allCells[currentIndex + 1];
        }
        // Wrap to first editable cell of next row
        var nextRow = row.nextElementSibling;
        while (nextRow && nextRow.tagName === 'TR') {
            var nextCells = nextRow.querySelectorAll('td.editable-cell[data-field]:not(.image-field)');
            if (nextCells.length > 0) {
                // Scroll the next row into view so the user can see it
                nextRow.scrollIntoView({ behavior: 'smooth', block: 'center' });
                return nextCells[0];
            }
            nextRow = nextRow.nextElementSibling;
        }
        return null;
    } else if (direction === 'prev') {
        // Try previous cell in same row
        if (currentIndex - 1 >= 0) {
            return allCells[currentIndex - 1];
        }
        // Wrap to last editable cell of previous row
        var prevRow = row.previousElementSibling;
        while (prevRow && prevRow.tagName === 'TR') {
            var prevCells = prevRow.querySelectorAll('td.editable-cell[data-field]:not(.image-field)');
            if (prevCells.length > 0) {
                prevRow.scrollIntoView({ behavior: 'smooth', block: 'center' });
                return prevCells[prevCells.length - 1];
            }
            prevRow = prevRow.previousElementSibling;
        }
        return null;
    }
    return null;
}

// ==========================================
// INLINE CELL EDITING
// ==========================================

function startCellEdit(cell) {
    if (cell.querySelector('input, textarea, select')) return; // Already editing
    if (cell.classList.contains('editing')) return; // Already in edit mode
    
    // Skip image fields and non-editable cells
    if (cell.classList.contains('image-field')) return;
    if (!cell.classList.contains('editable-cell')) return;
    var ft = (cell.getAttribute('data-field-type') || '').toLowerCase();
    if (ft === 'image') return;
    var fn = (cell.getAttribute('data-field') || '').toLowerCase();
    if (fn.includes('photo') || fn.includes('image') || fn.includes('picture')) return;
    
    // Mark cell as editing to prevent duplicate clicks (Phase 5)
    cell.classList.add('editing');
    
    const field = cell.getAttribute('data-field');
    const fieldType = cell.getAttribute('data-field-type') || '';
    const cardId = cell.closest('tr').getAttribute('data-card-id');
    // Read from .cell-value span if present, otherwise fallback to textContent
    const valueSpan = cell.querySelector('.cell-value');
    const currentValue = valueSpan ? valueSpan.textContent.trim() : cell.textContent.trim();
    const originalWidth = cell.offsetWidth;
    const originalHeight = cell.offsetHeight;
    // Ensure minimum editing width of ~20 chars (180px)
    const MIN_EDIT_WIDTH = 180;
    const effectiveWidth = Math.max(originalWidth, MIN_EDIT_WIDTH);

    // Lock cell dimensions to prevent column/row shrinking when content is replaced
    cell.style.minWidth = effectiveWidth + 'px';
    cell.style.minHeight = originalHeight + 'px';
    cell.style.width = effectiveWidth + 'px';
    cell.style.height = originalHeight + 'px';
    
    let editElement;
    
    // Detect multi-line based on actual cell rendering height (not char count)
    const computedStyle = getComputedStyle(cell);
    const cellLineHeight = parseFloat(computedStyle.lineHeight) || 18;
    const vertPad = parseFloat(computedStyle.paddingTop) + parseFloat(computedStyle.paddingBottom);
    const contentHeight = originalHeight - vertPad;
    const isMultiLine = contentHeight > (cellLineHeight * 1.5) || currentValue.includes('\n');
    
    // Store original value
    cell.setAttribute('data-original-value', currentValue);
    
    if (isMultiLine) {
        // Flex wrapper fills cell and vertically centers the textarea
        const wrapper = document.createElement('div');
        wrapper.className = 'inline-edit-wrapper';
        wrapper.style.cssText = `
            position: absolute;
            top: 0; left: 0; right: 0; bottom: 0;
            display: flex;
            align-items: center;
            z-index: 5;
            background: white;
            border: 2px solid #007bff;
            box-shadow: inset 0 0 5px rgba(0, 123, 255, 0.3);
            padding: 2px;
        `;
        
        editElement = document.createElement('textarea');
        editElement.value = currentValue;
        editElement.className = 'inline-edit-textarea';
        editElement.style.cssText = `
            width: 100%;
            max-height: 100%;
            box-sizing: border-box;
            padding: 1px 4px;
            border: none !important;
            box-shadow: none !important;
            font-size: inherit;
            font-family: inherit;
            background: transparent;
            outline: none;
            text-transform: uppercase;
            text-align: left;
            resize: none;
            overflow-y: auto;
            white-space: pre-wrap;
            word-wrap: break-word;
            line-height: 1.3;
        `;
        
        cell.style.position = 'relative';
        cell.style.overflow = 'hidden';
        cell.innerHTML = '';
        wrapper.appendChild(editElement);
        cell.appendChild(wrapper);
        
        // Auto-size textarea height to fit content
        editElement.style.height = 'auto';
        editElement.style.height = editElement.scrollHeight + 'px';
        
        // Re-size on input so textarea grows/shrinks with content
        editElement.addEventListener('input', function() {
            this.style.height = 'auto';
            this.style.height = this.scrollHeight + 'px';
        });
        
        editElement.focus();
        var len = editElement.value.length;
        editElement.setSelectionRange(len, len);
    } else {
        editElement = document.createElement('input');
        editElement.type = 'text';
        editElement.value = currentValue;
        editElement.className = 'inline-edit-input';
        editElement.style.cssText = `
            position: absolute;
            top: 0;
            left: 0;
            right: 0;
            bottom: 0;
            width: 100%;
            height: 100%;
            box-sizing: border-box;
            padding: 2px 6px;
            border: 2px solid #007bff;
            border-radius: 0;
            font-size: inherit;
            font-family: inherit;
            background: white;
            outline: none;
            box-shadow: inset 0 0 5px rgba(0, 123, 255, 0.3);
            text-transform: uppercase;
            text-align: left;
            display: block;
            margin: 0;
            z-index: 5;
        `;
        
        cell.style.position = 'relative';
        cell.style.overflow = 'hidden';
        cell.innerHTML = '';
        cell.appendChild(editElement);
        editElement.focus();
        var len = editElement.value.length;
        editElement.setSelectionRange(len, len);
    }
    
    // Handle blur - save on focus out (saveCellEdit is in edit-logic sub-module)
    editElement.addEventListener('blur', function() {
        const newVal = editElement.tagName === 'SELECT'
            ? editElement.options[editElement.selectedIndex].value
            : editElement.value;
        IDCardApp.saveCellEdit(cell, newVal, cardId, field);
    });
    
    // Handle keydown
    editElement.addEventListener('keydown', function(e) {
        if (e.key === 'Enter') {
            // Always save on Enter (no newline needed for inline cell edit)
            e.preventDefault();
            editElement.blur();
        } else if (e.key === 'Escape') {
            e.preventDefault();
            cancelCellEdit(cell);
        } else if (e.key === 'Tab') {
            e.preventDefault();
            editElement.blur();
            const adjacentCell = getAdjacentCell(cell, e.shiftKey ? 'prev' : 'next');
            if (adjacentCell) {
                startCellEdit(adjacentCell);
            }
        }
    });
}

function cancelCellEdit(cell) {
    const originalValue = cell.getAttribute('data-original-value') || '';
    const esc = window.escapeHtml || ((s) => { const d = document.createElement('div'); d.textContent = s; return d.innerHTML; });
    cell.innerHTML = `<span class="cell-value">${esc(originalValue)}</span>`;
    cell.style.position = '';
    cell.style.overflow = '';
    cell.style.padding = '';
    // Unlock cell dimensions
    cell.style.minWidth = '';
    cell.style.minHeight = '';
    cell.style.width = '';
    cell.style.height = '';
    cell.removeAttribute('data-original-value');
    cell.classList.remove('editing');
}

// ==========================================
// EDITABLE CELL HINTS (CSS)
// ==========================================

// Add tooltip hint for editable cells
function addEditableHints() {
    const style = document.createElement('style');
    style.textContent = `
        td.editable-cell:hover,
        td[data-field]:not(.checkbox-column):not(.action-column):not(.image-field):hover {
            cursor: text;
            background-color: rgba(0, 123, 255, 0.05);
        }
        
        td.editable-cell,
        td[data-field]:not(.checkbox-column):not(.action-column):not(.image-field) {
            position: relative;
        }
        
        td.editable-cell::after,
        td[data-field]:not(.checkbox-column):not(.action-column):not(.image-field)::after {
            content: '';
            position: absolute;
            right: 2px;
            top: 2px;
            width: 0;
            height: 0;
            border-left: 6px solid transparent;
            border-top: 6px solid rgba(0, 123, 255, 0.3);
            opacity: 0;
            transition: opacity 0.2s;
        }
        
        td.editable-cell:hover::after,
        td[data-field]:not(.checkbox-column):not(.action-column):not(.image-field):hover::after {
            opacity: 1;
        }
        
        .inline-edit-input:focus {
            outline: none;
            border-color: #0056b3;
        }
        
        .saving-indicator {
            animation: pulse 1s infinite;
        }
        
        @keyframes pulse {
            0%, 100% { opacity: 1; }
            50% { opacity: 0.5; }
        }
    `;
    document.head.appendChild(style);
}

// ==========================================
// IMAGE CELLS - CLICK TO VIEW
// ==========================================

function initImageCellHandlers() {
    document.querySelectorAll('.photo-thumbnail, .id-photo-cell img').forEach(img => {
        img.style.cursor = 'pointer';
        img.addEventListener('click', function(e) {
            e.stopPropagation();
            const fullSrc = this.src.replace('/thumbnails/', '/');
            openImagePreview(fullSrc);
        });
    });
}

function openImagePreview(src) {
    // Create overlay
    const overlay = document.createElement('div');
    overlay.className = 'image-preview-overlay';
    overlay.style.cssText = `
        position: fixed;
        top: 0;
        left: 0;
        width: 100vw;
        height: 100vh;
        background: rgba(0, 0, 0, 0.9);
        display: flex;
        align-items: center;
        justify-content: center;
        z-index: 10000;
        cursor: pointer;
    `;
    
    // Create image
    const img = document.createElement('img');
    img.src = src;
    img.style.cssText = `
        max-width: 90vw;
        max-height: 90vh;
        object-fit: contain;
        border-radius: 8px;
        box-shadow: 0 10px 50px rgba(0, 0, 0, 0.5);
    `;
    
    // Close hint
    const hint = document.createElement('div');
    hint.textContent = 'Click anywhere to close';
    hint.style.cssText = `
        position: absolute;
        bottom: 20px;
        left: 50%;
        transform: translateX(-50%);
        color: white;
        font-size: 14px;
        opacity: 0.7;
    `;
    
    overlay.appendChild(img);
    overlay.appendChild(hint);
    document.body.appendChild(overlay);
    
    // Close on click
    overlay.addEventListener('click', function() {
        document.body.removeChild(overlay);
    });
    
    // Close on escape
    document.addEventListener('keydown', function closeOnEscape(e) {
        if (e.key === 'Escape') {
            if (document.body.contains(overlay)) {
                document.body.removeChild(overlay);
            }
            document.removeEventListener('keydown', closeOnEscape);
        }
    });
}

// ==========================================
// EXPORTS
// ==========================================

IDCardApp.startCellEdit = startCellEdit;
IDCardApp.cancelCellEdit = cancelCellEdit;
IDCardApp.getAdjacentCell = getAdjacentCell;
IDCardApp.addEditableHints = addEditableHints;
IDCardApp.openImagePreview = openImagePreview;
IDCardApp.initImageCellHandlers = initImageCellHandlers;

})();


/* ── js/idcard-actions-edit-logic.js ── */

// ID Card Actions - Edit Logic Sub-module
// Contains: Save cell edit, make cells editable, Alpine bridge, init
// Split from: idcard-actions-edit.js

(function() {
'use strict';

window.IDCardApp = window.IDCardApp || {};

function _isClassLikeField(fieldName) {
    var f = String(fieldName || '').trim().toUpperCase();
    return f === 'CLASS' || f === 'STD' || f === 'STANDARD' || f === 'GRADE';
}

function _isSectionLikeField(fieldName) {
    var f = String(fieldName || '').trim().toUpperCase();
    return f === 'SECTION' || f === 'SEC' || f === 'DIV' || f === 'DIVISION';
}

function _isCourseLikeField(fieldName) {
    var f = String(fieldName || '').trim().toUpperCase();
    return f === 'COURSE' || f === 'PROGRAM' || f === 'PROGRAMME';
}

function _isBranchLikeField(fieldName) {
    var f = String(fieldName || '').trim().toUpperCase();
    return f === 'BRANCH' || f === 'STREAM' || f === 'DEPT' || f === 'DEPARTMENT';
}

function _normalizeFilterText(value) {
    return String(value || '').trim().toUpperCase();
}

function _normalizeCompactFilterText(value) {
    return _normalizeFilterText(value).replace(/[^A-Z0-9]+/g, '');
}

function _getRowFieldValueByKind(row, kind) {
    if (!row) return '';
    var cells = row.querySelectorAll('td[data-field]');
    for (var i = 0; i < cells.length; i++) {
        var field = String(cells[i].getAttribute('data-field') || '');
        var isMatch = false;
        if (kind === 'class') isMatch = _isClassLikeField(field);
        else if (kind === 'section') isMatch = _isSectionLikeField(field);
        else if (kind === 'course') isMatch = _isCourseLikeField(field);
        else if (kind === 'branch') isMatch = _isBranchLikeField(field);
        if (!isMatch) continue;
        var valNode = cells[i].querySelector('.cell-value');
        var raw = valNode ? valNode.textContent : cells[i].textContent;
        return String(raw || '').trim();
    }
    return '';
}

function _rowMatchesActiveClassSectionFilters(row, editedField, editedValue) {
    var classValue = _isClassLikeField(editedField)
        ? String(editedValue || '')
        : _getRowFieldValueByKind(row, 'class');
    var sectionValue = _isSectionLikeField(editedField)
        ? String(editedValue || '')
        : _getRowFieldValueByKind(row, 'section');
    var courseValue = _isCourseLikeField(editedField)
        ? String(editedValue || '')
        : _getRowFieldValueByKind(row, 'course');
    var branchValue = _isBranchLikeField(editedField)
        ? String(editedValue || '')
        : _getRowFieldValueByKind(row, 'branch');

    var classFilter = _normalizeFilterText(IDCardApp.currentClassFilter);
    var sectionFilter = _normalizeFilterText(IDCardApp.currentSectionFilter);
    var courseFilter = _normalizeFilterText(IDCardApp.currentCourseFilter);
    var branchFilter = _normalizeFilterText(IDCardApp.currentBranchFilter);
    var classMatches = !classFilter || _normalizeFilterText(classValue) === classFilter;
    var sectionMatches = !sectionFilter || _normalizeFilterText(sectionValue) === sectionFilter;
    var courseMatches = !courseFilter || _normalizeCompactFilterText(courseValue) === _normalizeCompactFilterText(courseFilter);
    var branchMatches = !branchFilter || _normalizeCompactFilterText(branchValue) === _normalizeCompactFilterText(branchFilter);
    return classMatches && sectionMatches && courseMatches && branchMatches;
}

// ==========================================
// SAVE CELL EDIT
// ==========================================

function saveCellEdit(cell, newValue, cardId, field) {
    const originalValue = cell.getAttribute('data-original-value') || '';
    
    // Check if this is an image field  image paths must NOT be uppercased
    const fieldType = (cell.getAttribute('data-field-type') || '').toLowerCase();
    const IMAGE_TYPES = ['photo', 'rel_photo', 'mother_photo', 'father_photo', 'barcode', 'qr_code', 'signature', 'image'];
    const isImageField = IMAGE_TYPES.includes(fieldType);
    
    // Convert to uppercase only for non-image text fields
    const finalValue = (typeof newValue === 'string' && !isImageField) ? newValue.toUpperCase() : newValue;
    
    //  Basic field validation via FieldClassifier 
    if (window.FieldClassifier && typeof newValue === 'string' && !isImageField) {
        var vResult = window.FieldClassifier.validate(field, fieldType, finalValue);
        if (!vResult.valid) {
            // Show error, restore cell
            if (typeof showToast === 'function') showToast(vResult.message, 'error');
            cell.style.backgroundColor = '#f8d7da';
            setTimeout(function() { cell.style.backgroundColor = ''; }, 2000);
            const esc = window.escapeHtml || ((s) => { const d = document.createElement('div'); d.textContent = s; return d.innerHTML; });
            cell.innerHTML = `<span class="cell-value">${esc(originalValue)}</span>`;
            cell.style.position = '';
            cell.style.overflow = '';
            cell.style.padding = '';
            cell.style.minWidth = '';
            cell.style.minHeight = '';
            cell.style.width = '';
            cell.style.height = '';
            cell.removeAttribute('data-original-value');
            cell.classList.remove('editing');
            return;
        }
    }
    
    // If no change, just restore
    if (finalValue === originalValue) {
        const esc = window.escapeHtml || ((s) => { const d = document.createElement('div'); d.textContent = s; return d.innerHTML; });
        cell.innerHTML = `<span class="cell-value">${esc(originalValue)}</span>`;
        cell.style.position = '';
        cell.style.overflow = '';
        cell.style.padding = '';
        cell.style.minWidth = '';
        cell.style.minHeight = '';
        cell.style.width = '';
        cell.style.height = '';
        cell.removeAttribute('data-original-value');
        cell.classList.remove('editing');
        return;
    }
    
    // Show loading state
    cell.innerHTML = '<span class="saving-indicator">Saving...</span>';
    cell.querySelector('.saving-indicator').style.cssText = `
        color: #666;
        font-style: italic;
    `;
    
    // Save via API
    ApiClient.post(`/api/card/${cardId}/update-field/`, {
        field: field,
        value: finalValue
    })
    .then(data => {
        const esc = window.escapeHtml || ((s) => { const d = document.createElement('div'); d.textContent = s; return d.innerHTML; });
        cell.innerHTML = `<span class="cell-value">${esc(finalValue)}</span>`;
        cell.style.position = '';
        cell.style.overflow = '';
        cell.style.padding = '';
        cell.style.minWidth = '';
        cell.style.minHeight = '';
        cell.style.width = '';
        cell.style.height = '';
        cell.classList.remove('editing');
        // Update data-original-value so next edit reads the new value
        cell.setAttribute('data-original-value', finalValue);
        
        // Show success feedback
        cell.style.backgroundColor = '#d4edda';
        setTimeout(() => {
            cell.style.backgroundColor = '';
        }, 1000);
        
        if (typeof showToast === 'function') {
            showToast('Field updated successfully', 'success');
        }
        
        //  Check if row should be removed from current filtered view 
        // If a class/section/course/branch filter is active and we just changed that field,
        // the row may no longer match the filter  animate it out.
        const fieldUpper = field.toUpperCase();
        const row = cell.closest('tr');
        var changedClassOrSection = _isClassLikeField(fieldUpper)
            || _isSectionLikeField(fieldUpper)
            || _isCourseLikeField(fieldUpper)
            || _isBranchLikeField(fieldUpper);
        var hasClassOrSectionFilter = !!IDCardApp.currentClassFilter
            || !!IDCardApp.currentSectionFilter
            || !!IDCardApp.currentCourseFilter
            || !!IDCardApp.currentBranchFilter;

        if (changedClassOrSection && hasClassOrSectionFilter && row && cardId) {
            var stillMatches = _rowMatchesActiveClassSectionFilters(row, fieldUpper, finalValue);
            if (!stillMatches && typeof IDCardApp.removeCardRow === 'function') {
                IDCardApp.removeCardRow(cardId);
            } else if (typeof IDCardApp.applyFiltersAndSort === 'function') {
                IDCardApp.applyFiltersAndSort();
            } else if (typeof applyFiltersAndSort === 'function') {
                applyFiltersAndSort();
            }
        } else {
            // No filter active for this field, just re-apply date filter
            if (typeof IDCardApp.applyFiltersAndSort === 'function') {
                IDCardApp.applyFiltersAndSort();
            } else if (typeof applyFiltersAndSort === 'function') {
                applyFiltersAndSort();
            }
        }
        
        // Refresh filter dropdown options in case new values were introduced
        // (debounced in populateFilterOptions if it fires too often)
        if (typeof IDCardApp.populateFilterOptions === 'function') {
            IDCardApp.populateFilterOptions();
        } else if (typeof populateFilterOptions === 'function') {
            populateFilterOptions();
        }
    })
    .catch(error => {
        console.error('Error updating field:', error);
        const esc = window.escapeHtml || ((s) => { const d = document.createElement('div'); d.textContent = s; return d.innerHTML; });
        cell.innerHTML = `<span class="cell-value">${esc(originalValue)}</span>`;
        cell.style.position = '';
        cell.style.overflow = '';
        cell.style.padding = '';
        cell.style.minWidth = '';
        cell.style.minHeight = '';
        cell.style.width = '';
        cell.style.height = '';
        cell.classList.remove('editing');
        cell.removeAttribute('data-original-value');
        
        // Show error feedback
        cell.style.backgroundColor = '#f8d7da';
        setTimeout(() => {
            cell.style.backgroundColor = '';
        }, 2000);
        
        if (typeof showToast === 'function') {
            showToast('Failed to update field', 'error');
        }
    });
}

// ==========================================
// EDITABLE CELLS INITIALIZATION
// ==========================================

function makeTableCellsEditable() {
    const table = document.getElementById('data-table');
    if (!table) return;
    
    // Single click to edit for faster editing
    table.addEventListener('click', function(e) {
        const cell = e.target.closest('td[data-field]');
        if (!cell) return;
        
        // Check if cell is editable
        const field = cell.getAttribute('data-field');
        if (!field) return;
        
        // Don't edit checkbox or action columns
        if (cell.classList.contains('checkbox-column') || 
            cell.classList.contains('action-column') ||
            cell.querySelector('input[type="checkbox"]')) {
            return;
        }
        
        // Don't edit image fields via inline edit
        const ft = (cell.getAttribute('data-field-type') || '').toLowerCase();
        if (ft === 'image' ||
            field.toLowerCase().includes('photo') || 
            field.toLowerCase().includes('image') ||
            field.toLowerCase().includes('picture')) {
            return;
        }
        
        // Prevent re-triggering if already editing
        if (cell.classList.contains('editing')) {
            return;
        }
        
        // startCellEdit is in edit-ui sub-module
        IDCardApp.startCellEdit(cell);
    });
}

// ==========================================
// ALPINE BRIDGE
// ==========================================

/**
 * Alpine inlineEditState() bridge.
 * Called by the Alpine component's saveEdit() method.
 * Uses the same API endpoint as the vanilla JS production code.
 *
 * @param {string|number} cardId
 * @param {string} fieldName
 * @param {string} value
 * @returns {Promise<boolean>} true on success
 */
window.saveInlineEdit = async function (cardId, fieldName, value) {
    try {
        // Uppercase non-image text fields (same logic as saveCellEdit)
        var IMAGE_TYPES = ['photo', 'rel_photo', 'mother_photo', 'father_photo', 'barcode', 'qr_code', 'signature', 'image'];
        var finalValue = (!IMAGE_TYPES.includes(fieldName) && typeof value === 'string') ? value.toUpperCase() : value;

        var data = await ApiClient.post('/api/card/' + cardId + '/update-field/', {
            field: fieldName,
            value: finalValue
        });

        var row = document.querySelector('tr[data-card-id="' + cardId + '"]');
        var fieldUpper = String(fieldName || '').toUpperCase();
        var changedClassOrSection = _isClassLikeField(fieldUpper)
            || _isSectionLikeField(fieldUpper)
            || _isCourseLikeField(fieldUpper)
            || _isBranchLikeField(fieldUpper);
        var hasClassOrSectionFilter = !!IDCardApp.currentClassFilter
            || !!IDCardApp.currentSectionFilter
            || !!IDCardApp.currentCourseFilter
            || !!IDCardApp.currentBranchFilter;

        if (changedClassOrSection && hasClassOrSectionFilter && row && cardId) {
            var stillMatches = _rowMatchesActiveClassSectionFilters(row, fieldUpper, finalValue);
            if (!stillMatches && typeof IDCardApp.removeCardRow === 'function') {
                IDCardApp.removeCardRow(cardId);
            } else if (typeof IDCardApp.applyFiltersAndSort === 'function') {
                IDCardApp.applyFiltersAndSort();
            }
        } else if (typeof IDCardApp.applyFiltersAndSort === 'function') {
            IDCardApp.applyFiltersAndSort();
        }

        if (typeof IDCardApp.populateFilterOptions === 'function') {
            IDCardApp.populateFilterOptions();
        }

        if (typeof showToast === 'function') showToast('Field updated', 'success');
        return true;
    } catch (err) {
        console.error('saveInlineEdit error:', err);
        if (typeof showToast === 'function') showToast('Failed to save', 'error');
        return false;
    }
};

// ==========================================
// INITIALIZATION
// ==========================================

function initEditModule() {
    makeTableCellsEditable();
    IDCardApp.addEditableHints();
    IDCardApp.initImageCellHandlers();
}

// ==========================================
// EXPORTS
// ==========================================

IDCardApp.saveCellEdit = saveCellEdit;
IDCardApp.makeTableCellsEditable = makeTableCellsEditable;
IDCardApp.initEditModule = initEditModule;
IDCardApp.saveInlineEdit = window.saveInlineEdit;

})();


/* ── js/idcard-actions.js ── */

// ID Card Actions - Main Entry Point
// This file orchestrates all module initializations
// 
// Module load order in HTML should be:
// 1. idcard-actions-core.js    - Core utilities, CSRF, toast, sidebar
// 2. idcard-actions-table.js   - Table rendering, pagination, lazy loading
// 3. idcard-actions-search.js  - Search, filter, sort functionality
// 4. idcard-actions-upload.js  - XLSX/ZIP upload functionality
// 5. idcard-actions-download.js - Download images, DOCX, XLSX
// 6. idcard-actions-modal.js   - Side modal, delete modal
// 7. idcard-actions-api.js     - API calls, bulk operations
// 8. idcard-actions-edit.js    - Inline cell editing
// 9. idcard-actions.js         - This file (main initialization)

(function() {
    'use strict';
    
    // ==========================================
    // MODULE VERIFICATION
    // ==========================================
    
    function verifyModulesLoaded() {
        const requiredModules = [
            'initCoreModule',
            'initTableModule', 
            'initSearchModule',
            'initUploadModule',
            'initDownloadModule',
            'initModalModule',
            'initApiModule',
            'initEditModule'
        ];
        
        const missingModules = [];
        
        requiredModules.forEach(moduleName => {
            if (!window.IDCardApp || typeof window.IDCardApp[moduleName] !== 'function') {
                missingModules.push(moduleName);
            }
        });
        
        if (missingModules.length > 0) {
            console.warn('IDCard Actions: Missing modules:', missingModules);
            return false;
        }
        
        return true;
    }
    
    // ==========================================
    // MAIN INITIALIZATION
    // ==========================================
    
    function initializeApp() {
        // Set global table ID from template variable
        if (typeof TABLE_ID !== 'undefined') {
            window.IDCardApp.tableId = TABLE_ID;
        }
        if (typeof CURRENT_STATUS !== 'undefined') {
            window.IDCardApp.currentStatus = CURRENT_STATUS;
        }
        if (typeof CLIENT_ID !== 'undefined') {
            window.IDCardApp.clientId = CLIENT_ID;
        }
        
        // Verify all modules are loaded
        if (!verifyModulesLoaded()) {
            console.error('IDCard Actions: Some modules failed to load. Check script order in HTML.');
        }
        
        // Initialize modules in order (each wrapped individually so one failure
        // doesn't prevent the rest from loading  defensive against cross-IIFE issues)
        var _modules = [
            ['initCoreModule',    'Core'],
            ['initTableModule',   'Table'],
            ['initSearchModule',  'Search'],
            ['initUploadModule',  'Upload'],
            ['initDownloadModule','Download'],
            ['initModalModule',   'Modal'],
            ['initApiModule',     'API'],
            ['initEditModule',    'Edit'],
            ['initCropModule',    'Crop']
        ];

        _modules.forEach(function(m) {
            try {
                if (window.IDCardApp && typeof window.IDCardApp[m[0]] === 'function') {
                    window.IDCardApp[m[0]]();
                }
            } catch (error) {
                console.error('IDCard Actions: ' + m[1] + ' module init failed:', error);
            }
        });

        // Dispatch custom event for other scripts that may depend on this
        document.dispatchEvent(new CustomEvent('idcard-actions-ready'));
    }
    
    // ==========================================
    // KEYBOARD SHORTCUTS
    // ==========================================
    
    function initKeyboardShortcuts() {
        document.addEventListener('keydown', function(e) {
            // Ctrl+F or Cmd+F - Focus search
            if ((e.ctrlKey || e.metaKey) && e.key === 'f') {
                const searchInput = document.getElementById('searchInput');
                if (searchInput) {
                    e.preventDefault();
                    searchInput.focus();
                    searchInput.select();
                }
            }
            
            // Escape - Close any open modal (unified handler)
            if (e.key === 'Escape') {
                // Close side modal
                const sideModal = document.getElementById('sideModalOverlay');
                if (sideModal && sideModal.classList.contains('active')) {
                    if (typeof closeSideModal === 'function') closeSideModal();
                    e.preventDefault();
                    return;
                }
                
                // Close permanent delete modal
                const deleteModal = document.getElementById('deleteModalOverlay');
                if (deleteModal && deleteModal.classList.contains('active')) {
                    if (typeof closeDeleteModalFn === 'function') closeDeleteModalFn();
                    else deleteModal.classList.remove('active');
                    document.body.style.overflow = '';
                    e.preventDefault();
                    return;
                }
                
                // Close simple delete modal
                const simpleDeleteModal = document.getElementById('simpleDeleteModalOverlay');
                if (simpleDeleteModal && simpleDeleteModal.classList.contains('active')) {
                    if (typeof closeSimpleDeleteModalFn === 'function') closeSimpleDeleteModalFn();
                    else simpleDeleteModal.classList.remove('active');
                    document.body.style.overflow = '';
                    e.preventDefault();
                    return;
                }
                
                // Close upload modal
                const uploadModal = document.getElementById('uploadModalOverlay');
                if (uploadModal && uploadModal.classList.contains('active')) {
                    uploadModal.classList.remove('active');
                    document.body.style.overflow = '';
                    e.preventDefault();
                    return;
                }
                
                // Close image sort modal
                const imageSortModal = document.getElementById('imageSortModalOverlay');
                if (imageSortModal && imageSortModal.classList.contains('active')) {
                    imageSortModal.classList.remove('active');
                    e.preventDefault();
                    return;
                }
                
                // Close search all modal
                const searchAllModal = document.getElementById('searchAllModalOverlay');
                if (searchAllModal && searchAllModal.classList.contains('active')) {
                    searchAllModal.classList.remove('active');
                    e.preventDefault();
                    return;
                }
                
                // Close doc format modal
                const docFormatModal = document.getElementById('docFormatModalOverlay');
                if (docFormatModal && docFormatModal.classList.contains('active')) {
                    docFormatModal.classList.remove('active');
                    e.preventDefault();
                    return;
                }
            }
            
            // Ctrl+A or Cmd+A - Select all in table
            if ((e.ctrlKey || e.metaKey) && e.key === 'a') {
                const activeElement = document.activeElement;
                // Only if not in an input/textarea
                if (!activeElement.matches('input, textarea')) {
                    const selectAllCheckbox = document.getElementById('selectAll');
                    if (selectAllCheckbox) {
                        e.preventDefault();
                        selectAllCheckbox.checked = true;
                        selectAllCheckbox.dispatchEvent(new Event('change', { bubbles: true }));
                    }
                }
            }
            
            // N key - Add new card (when not in input)
            if (e.key === 'n' && !e.ctrlKey && !e.metaKey && !e.altKey) {
                const activeElement = document.activeElement;
                if (!activeElement.matches('input, textarea')) {
                    const addBtn = document.getElementById('addNewBtn');
                    if (addBtn) {
                        e.preventDefault();
                        addBtn.click();
                    }
                }
            }
            
            // T key - Go to top of list (first row)
            if (e.key === 't' && !e.ctrlKey && !e.metaKey && !e.altKey) {
                const activeElement = document.activeElement;
                if (!activeElement.matches('input, textarea')) {
                    e.preventDefault();
                    goToTableTop();
                }
            }
            
            // B key - Go to bottom of list (last row)
            if (e.key === 'b' && !e.ctrlKey && !e.metaKey && !e.altKey) {
                const activeElement = document.activeElement;
                if (!activeElement.matches('input, textarea')) {
                    e.preventDefault();
                    goToTableBottom();
                }
            }
        });
    }
    
    // Go to top of table (SR No. 1)
    function goToTableTop() {
        const tableBody = document.getElementById('cardsTableBody');
        const tableContainer = document.querySelector('.table-container');
        
        if (tableBody && tableContainer) {
            // Scroll to top
            tableContainer.scrollTop = 0;
            
            // Select first row
            const firstRow = tableBody.querySelector('tr');
            if (firstRow) {
                // Clear any existing selection
                document.querySelectorAll('#cardsTableBody tr.selected').forEach(row => {
                    row.classList.remove('selected');
                    const checkbox = row.querySelector('.rowCheckbox');
                    if (checkbox) checkbox.checked = false;
                });
                
                // Select first row
                firstRow.classList.add('selected');
                const checkbox = firstRow.querySelector('.rowCheckbox');
                if (checkbox) checkbox.checked = true;
                
                // Update selection count
                if (typeof window.IDCardApp.updateButtonStates === 'function') {
                    window.IDCardApp.updateButtonStates();
                }
                
                // Scroll into view
                firstRow.scrollIntoView({ behavior: 'smooth', block: 'center' });
            }
        }
    }
    
    // Go to bottom of table (last SR No.)
    function goToTableBottom() {
        const tableBody = document.getElementById('cardsTableBody');
        const tableContainer = document.querySelector('.table-container');
        
        if (tableBody && tableContainer) {
            // First, load all remaining data if lazy loading is active
            if (window.IDCardApp && window.IDCardApp.lazyLoadState) {
                const state = window.IDCardApp.lazyLoadState;
                if (state.hasMore && typeof window.IDCardApp.loadMoreData === 'function') {
                    // Load all remaining data first
                    loadAllRemainingData().then(() => {
                        scrollToLastRow();
                    });
                } else {
                    scrollToLastRow();
                }
            } else {
                scrollToLastRow();
            }
        }
    }
    
    // Helper to scroll to and select last row
    function scrollToLastRow() {
        const tableBody = document.getElementById('cardsTableBody');
        const tableContainer = document.querySelector('.table-container');
        
        if (tableBody && tableContainer) {
            const rows = tableBody.querySelectorAll('tr');
            const lastRow = rows[rows.length - 1];
            
            if (lastRow) {
                // Scroll to bottom
                tableContainer.scrollTop = tableContainer.scrollHeight;
                
                // Clear any existing selection
                document.querySelectorAll('#cardsTableBody tr.selected').forEach(row => {
                    row.classList.remove('selected');
                    const checkbox = row.querySelector('.rowCheckbox');
                    if (checkbox) checkbox.checked = false;
                });
                
                // Select last row
                lastRow.classList.add('selected');
                const checkbox = lastRow.querySelector('.rowCheckbox');
                if (checkbox) checkbox.checked = true;
                
                // Update selection count
                if (typeof window.IDCardApp.updateButtonStates === 'function') {
                    window.IDCardApp.updateButtonStates();
                }
                
                // Scroll into view
                lastRow.scrollIntoView({ behavior: 'smooth', block: 'center' });
            }
        }
    }
    
    // Load all remaining data for going to bottom
    async function loadAllRemainingData() {
        if (!window.IDCardApp || !window.IDCardApp.lazyLoadState) return;
        
        const state = window.IDCardApp.lazyLoadState;
        while (state.hasMore && typeof window.IDCardApp.loadMoreData === 'function') {
            await new Promise(resolve => {
                window.IDCardApp.loadMoreData();
                setTimeout(resolve, 100); // Wait a bit between loads
            });
        }
    }
    
    // ==========================================
    // WINDOW RESIZE HANDLER
    // ==========================================
    
    let resizeTimeout;
    function initResizeHandler() {
        window.addEventListener('resize', function() {
            clearTimeout(resizeTimeout);
            resizeTimeout = setTimeout(function() {
                // Re-adjust table alignment
                if (typeof window.IDCardApp.applyDynamicAlignment === 'function') {
                    window.IDCardApp.applyDynamicAlignment();
                }
                
                // Re-check lazy loading
                if (typeof window.IDCardApp.checkLoadMore === 'function') {
                    window.IDCardApp.checkLoadMore();
                }
            }, 250);
        });
    }
    
    // ==========================================
    // PERFORMANCE MONITORING
    // ==========================================
    
    function logPerformance() {
        // Performance logging disabled in production
    }
    
    // ==========================================
    // DOM READY HANDLER
    // ==========================================
    
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', function() {
            initializeApp();
            initKeyboardShortcuts();
            initResizeHandler();
            logPerformance();
        });
    } else {
        // DOM already loaded
        initializeApp();
        initKeyboardShortcuts();
        initResizeHandler();
        logPerformance();
    }

    // Handle bfcache restore (browser back button)  reinitialize table
    // from scratch so data loads from offset=0 (sr_no 1) instead of stale state.
    window.addEventListener('pageshow', function(e) {
        if (e.persisted) {
            initializeApp();
        }
    });
    
    // ==========================================
    // PUBLIC API
    // ==========================================
    
    // Expose a clean public API
    window.IDCardActions = {
        version: '2.0.0',
        modules: window.IDCardApp || {},
        
        // Utility functions
        showToast: function(message, type) {
            if (typeof showToast === 'function') {
                showToast(message, type);
            }
        },
        
        // Refresh table
        refreshTable: function() {
            if (window.IDCardApp && typeof window.IDCardApp.refreshCardTable === 'function') {
                window.IDCardApp.refreshCardTable();
            } else if (window.IDCardPage && typeof window.IDCardPage.navigateStatusNoReload === 'function') {
                window.IDCardPage.navigateStatusNoReload((typeof CURRENT_STATUS !== 'undefined' && CURRENT_STATUS) ? CURRENT_STATUS : 'pending');
            } else {
                console.warn('IDCardActions.refreshTable skipped: no refresh bridge available');
            }
        },
        
        // Get selected card IDs
        getSelected: function() {
            if (window.IDCardApp && typeof window.IDCardApp.getSelectedCardIds === 'function') {
                return window.IDCardApp.getSelectedCardIds();
            }
            return [];
        },
        
        // Open add modal
        openAddModal: function() {
            if (window.IDCardApp && typeof window.IDCardApp.openSideModal === 'function') {
                window.IDCardApp.openSideModal('add');
            }
        },
        
        // Reinitialize (useful after dynamic content changes)
        reinitialize: function() {
            initializeApp();
        }
    };
    
// IDCard Actions: Main module loaded (v2.0.0)
    
})();
